import tenacity
from tenacity import wait_exception, stop_after_attempt, retry


def test_probe_wait_exception_real_retry():
    sleeps = []
    calls = {"n": 0}

    def pred(exc):
        return 3.5 if isinstance(exc, ValueError) else 10.0

    @retry(wait=wait_exception(pred), stop=stop_after_attempt(3), sleep=sleeps.append)
    def f():
        calls["n"] += 1
        raise ValueError("x")

    try:
        f()
    except tenacity.RetryError:
        pass
    assert calls["n"] == 3
    assert sleeps == [3.5, 3.5]

