import logging

from tenacity import Retrying, stop_after_attempt
from tenacity.before_sleep import before_sleep_log


class CustomLogger:
    def __init__(self):
        self.calls = []

    def log(self, level, msg, *args, **kwargs):
        self.calls.append((level, msg))


def test_before_sleep_log_duck_typed_logger_on_retry():
    d = CustomLogger()
    attempts = {'n': 0}

    def flaky():
        attempts['n'] += 1
        if attempts['n'] < 2:
            raise ValueError('boom')
        return 1

    r = Retrying(stop=stop_after_attempt(3), before_sleep=before_sleep_log(d, logging.WARNING))
    assert r(flaky) == 1
    assert len(d.calls) >= 1
    assert all(level == logging.WARNING for level, _ in d.calls)

