from tenacity import Retrying, stop_after_attempt, wait_fixed, before_log, after_log, before_sleep_log


class DuckLogger:
    def __init__(self):
        self.calls = []

    def log(self, level, msg, *args, **kwargs):
        self.calls.append((level, msg))


def test_duck_logger_receives_calls_from_helpers():
    logger = DuckLogger()
    state = {'n': 0}

    def flaky():
        state['n'] += 1
        if state['n'] < 2:
            raise ValueError('boom')
        return 1

    r = Retrying(
        stop=stop_after_attempt(3),
        wait=wait_fixed(0),
        before=before_log(logger, 10),
        after=after_log(logger, 10),
        before_sleep=before_sleep_log(logger, 10),
    )
    assert r(flaky) == 1
    # before_log fires on each attempt (2), after_log on each attempt (2), before_sleep once (1)
    assert len(logger.calls) == 5, logger.calls
    assert all(isinstance(m, str) for _, m in logger.calls)

